scription": "[centralmaineadaptivesports.org](https://centralmaineadaptivesports.org)", "city": "Auburn", "state": "ME", "aliases": [], "places": [{"position": 0, "label": null, "address": "200 Lost Valley Rd", "city": "Auburn", "state": "ME", "postal_code": "04210"}]}, {"name": "Pineland Farms", "code": "PFI", "description": "[pinelandfarms.org](https://pinelandfarms.org/recreation/vast/)", "city": "New Gloucester", "state": "ME", "aliases": [], "places": [{"position": 0, "label": null, "address": "25 Campus Dr", "city": "New Gloucester", "state": "ME", "postal_code": "04260"}]}, {"name": "Cape Cod Curling Club", "code": "CCCC", "description": "[capecodcurling.org](https://www.capecodcurling.org)", "city": "Falmouth", "state": "MA", "aliases": [], "places": [{"position": 0, "label": null, "address": null, "city": "Falmouth", "state": "MA", "postal_code": "02541"}]}, {"name": "Town of Dennis", "code": "TD", "description": "[town.dennis.ma.us](https://www.town.dennis.ma.us/)", "city": "South Dennis", "state": "MA", "aliases": [], "places": [{"position": 0, "label": null, "address": "685 Rte 134", "city": "South Dennis", "state": "MA", "postal_code": "02660"}]}, {"name": "Pleasant Bay Community Boating", "code": "PBCB", "description": "[pbcb.cc](https://pbcb.cc)", "city": "Harwich", "state": "MA", "aliases": [], "places": [{"position": 0, "label": null, "address": "2287 Massachusetts 28", "city": "Harwich", "state": "MA", "postal_code": null}]}]$hub$::jsonb) loop
    continue when exists (
      select 1 from public.organizations o
       where lower(o.name) = lower(item ->> 'name')
          or lower(item ->> 'name') = any (select lower(a) from unnest(o.aliases) a)
    );
    code := item ->> 'code';
    tries := 0;
    while exists (select 1 from public.organizations o where o.short_code = code) loop
      tries := tries + 1;
      code := left(item ->> 'code', 2) || chr(65 + (tries / 26) % 26) || chr(65 + tries % 26);
    end loop;
    insert into public.organizations (short_code, name, city, state, description, aliases)
    values (code, item ->> 'name', item ->> 'city', item ->> 'state', item ->> 'description',
            array(select jsonb_array_elements_text(item -> 'aliases')))
    returning id into org;
    insert into public.organization_places
      (organization_id, position, label, address, city, state, postal_code)
    select org, (p ->> 'position')::integer, p ->> 'label', p ->> 'address', p ->> 'city',
           p ->> 'state', p ->> 'postal_code'
      from jsonb_array_elements(item -> 'places') p;
  end loop;
end;
$$;

-- Organizations here with no location, where the hub shows one.
insert into public.organization_places (organization_id, position, label, address, city, state, postal_code)
select o.id, 0, null, null, 'Los Angeles', 'CA', '90024-0856'
  from public.organizations o
 where o.name = 'The Unrecables'
   and not exists (select 1 from public.organization_places x where x.organization_id = o.id);
update public.organizations set city = coalesce(city, 'Los Angeles'), state = coalesce(state, 'CA')
 where name = 'The Unrecables';
